package main

import (
	"sync"
	"testing"
	"time"
)

func TestProbeCounters(t *testing.T) {
	store := NewStore(time.Minute)
	c, l, d := store.Counters()
	if c != 0 || l != 0 || d != 0 {
		t.Fatalf("fresh counters = %d/%d/%d, want 0/0/0", c, l, d)
	}
	store.Create("a", "u1")
	store.Create("b", "u2")
	store.Get("a")
	store.Get("missing")
	store.Delete("a")
	store.Delete("a") // idempotent, still counts
	c, l, d = store.Counters()
	if c != 2 {
		t.Fatalf("created = %d, want 2", c)
	}
	if l != 2 {
		t.Fatalf("lookups = %d, want 2", l)
	}
	if d != 2 {
		t.Fatalf("deletes = %d, want 2", d)
	}

	// Concurrent increments: total must match operations issued.
	conc := NewStore(time.Minute)
	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			for j := 0; j < 50; j++ {
				conc.Create("x", "u")
				conc.Get("x")
				conc.Delete("x")
			}
		}(i)
	}
	wg.Wait()
	c, l, d = conc.Counters()
	if c != 500 || l != 500 || d != 500 {
		t.Fatalf("concurrent counters = %d/%d/%d, want 500/500/500", c, l, d)
	}
}
EOF
